88|#[test]
89|fn test_find_fuzzy_search() {
90|    let dir = setup_workspace();
91|
92|    write(dir.path().join("authentication.md"), "# User Authentication\n\nAuth content.").unwrap();
93|    write(dir.path().join("database.md"), "# Database Config\n\nDB content.").unwrap();
94|    write(dir.path().join("api.md"), "# API Endpoints\n\nAPI content.").unwrap();
95|
96|    let (stdout, stderr, success) = run_iwe(dir.path(), &["auth", "-f", "json"]);
97|
98|    assert!(success, "stderr: {}", stderr);
99|
100|    let parsed: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
101|    let results = parsed["results"].as_array().unwrap();
102|
103|    assert!(!results.is_empty(), "Should find at least one result");
104|    assert_eq!(results[0]["key"], "authentication");
