107|#[test]
108|fn test_find_roots_only() {
109|    let dir = setup_workspace();
110|
111|    write(
112|        dir.path().join("parent.md"),
113|        indoc! {"
114|            # Parent
115|
116|            [child](child)
117|        "},
118|    )
119|    .unwrap();
120|
121|    write(dir.path().join("child.md"), "# Child\n\nChild content.").unwrap();
122|    write(dir.path().join("orphan.md"), "# Orphan\n\nNo references.").unwrap();
123|
124|    let (stdout, stderr, success) = run_iwe(dir.path(), &["--roots", "-f", "json"]);
125|
126|    assert!(success, "stderr: {}", stderr);
127|
128|    let parsed: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
129|    let results = parsed["results"].as_array().unwrap();
130|
131|    let keys: Vec<&str> = results.iter().map(|r| r["key"].as_str().unwrap()).collect();
132|
133|    assert!(keys.contains(&"parent"), "parent should be a root");
